import boto3

def embed_document_section(section_text):
    client = boto3.client('bedrock-runtime')

    payload = {
        'inputText': section_text,
        'textEmbedding': {
            'modelId': 'amazon.titan-embed-text-v1'
        }
    }

    response = client.invoke_model(
        body=json.dumps(payload),
        modelId='amazon.titan-embed-text-v1'
    )

    result = json.loads(response.get('body').read())
    return result.get('embedding')

import boto3

def extract_fields(document_bytes):
    textract_client = boto3.client('textract')
    response = textract_client.analyze_document(
        Document={'Bytes': document_bytes},
        FeatureTypes=['FORMS'])
    fields = {}
    for block in response['Blocks']:
        if block['BlockType'] == 'KEY_VALUE_SET':
            key = next((child['Text'] for child in block['Relationships'][0]['Ids'] if child['BlockType'] == 'WORD'), None)
            value = next((child['Text'] for child in block['Relationships'][1]['Ids'] if child['BlockType'] == 'WORD'), None)
            if key and value:
                fields[key] = value
    return fields

